const cleanJsonString = data.replace(/\n/g, '').trim();
const parsedData = JSON.parse(cleanJsonString);




return parsedData;

const mapDays = new Map([
  ["Sunday", "ראשון"],
  ["Monday", "שני"],
  ["Tuesday", "שלישי"],
  ["Wednesday", "רביעי"],
  ["Thursday", "חמישי"],
  ["Friday", "שישי"],
  ["Saturday", "שבת"]
]);

// חילוץ מערך הכבישים בצורה בטוחה
let roadsMsg = "";
const inputJson = $input.first().json;
const aiJson = $('מערך של הפגנות מתשובת AI').first()?.json;

if (aiJson && Array.isArray(aiJson.blocked_roads) && aiJson.blocked_roads.length > 0) {
  roadsMsg = aiJson.blocked_roads.join(" , ");
} else {
  roadsMsg = "אין חסימות ידועות";
}

// חילוץ יתר השדות
const dayName = $('Schedule Trigger').first()?.json?.['Day of week'];
const curDay = mapDays.get(dayName) || "לא צוין";

const startTime = inputJson.start_time || "לא צוין";
const endTime = inputJson.end_time || "לא צוין";
const place = inputJson.location || "לא צוין";
const title = inputJson.title || "";
const summary = inputJson.summary || "";
const source = inputJson.source || "";

// תו RLM לכיווניות RTL
const RLM = "\u200F";

const msg = 
`🚨 *התראת הפגנה חדשה* 🚨

${RLM}📌 *${title}*

🗓️ *יום:* יום ${curDay}
⏰ *שעות:* ${startTime} - ${endTime}
📍 *מיקום:* ${place}
📰 *מקור:* ${source}

📝 *תקציר:*
${summary}

${RLM}🛣️ *כבישים חסומים:* ${roadsMsg}`;

return [{
  json: {
    msg: msg
  }
}];

// אוסף את כל הכותרות והתוכן מכל ה-Items של ה-Merge
const allItems = $input.all();

const formattedNews = allItems.map((item, index) => {
  const title = item.json.title || item.json.contentSnippet || item.json.full_text || '';
  const desc = item.json.description || '';
  const contect = item.json.contentSnippet;
  const source  = item.json.link;
  return `${index + 1}. ${title} ${desc} ${contect} ${source}`.trim();
}).join('\n');

// מחזיר Item יחיד שנושא את כל הטקסט המאוחד
return [{
  json: {
    combined_news: formattedNews
  }
}];

// קבלת הטקסט מה-HTTP Request
const htmlContent = $input.first().json.data;

// Mako מציגים את המבזקים בין הביטוי "מבזקי חדשות" לבין סוף הרשימה
// או לחילופין, המבזקים מופרדים בעמוד בתו * (כוכבית) או בשורות חדשות עם שעה.

// ניקוי תגיות HTML בסיסיות לקבלת טקסט נקי
let cleanText = htmlContent.replace(/<[^>]*>/g, ' ');

// חילוץ המקטע שרק בו מופיעים המבזקים
const startIndex = cleanText.indexOf('מבזקי חדשות');
if (startIndex !== -1) {
  cleanText = cleanText.substring(startIndex);
}

// Mako מפרידים בין המבזקים בעזרת כוכביות (*)
const rawFlashes = cleanText.split('*');

const parsedFlashes = [];

for (let item of rawFlashes) {
  let text = item.trim().replace(/\s+/g, ' '); // ניקוי רווחים כפולים

  // סינון שורות ריקות או טקסטים של תפריטים (לפי אורך או תבנית שעה)
  if (text.length > 15 && /\d{1,2}:\d{2}/.test(text)) {

    // חילוץ השעה והתוכן
    const timeMatch = text.match(/(\d{1,2}:\d{2})/);
    const time = timeMatch ? timeMatch[1] : '';
    const content = text.replace(time, '').trim();

    parsedFlashes.push({
      json: {
        time: time,
        flash: content,
        full_text: `${time} - ${content}`,
        source: "חדשות 12"
      }
    });
  }
}

// החזרת מערך המבזקים הנקי
return parsedFlashes;

